<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getList, getPage, post } from '@/api/resources'
import { http, problemMessage } from '@/api/http'
import type { Asset, ParkEvent } from '@/types/domain'
import StatusTag from '@/components/StatusTag.vue'
import { formatDate } from '@/utils/format'

interface Statistics { total?: number; open?: number; closed?: number; closureRate?: number; averageProcessingHours?: number }
interface FloodPlan { id: string; name: string; content: string; status: string }
const events = ref<ParkEvent[]>([]); const assets = ref<Asset[]>([]); const statistics = ref<Statistics>({}); const plans = ref<FloodPlan[]>([]); const loading = ref(true); const error = ref(''); const dialog = ref(false); const planDialog = ref(false); const submitting = ref(false); const form = reactive({ title: '', category: 'Environment', severity: 'Warning', assetId: '', description: '', longitude: 121.43, latitude: 31.19 }); const plan = reactive({ name: '', content: '', status: 'Active' })
async function load(): Promise<void> { loading.value = true; error.value = ''; try { const [eventData, assetData, statsData, planData] = await Promise.all([getPage<ParkEvent>('/emergency/events'), getPage<Asset>('/assets', { pageSize: 100 }), http.get<Statistics>('/emergency/statistics'), getList<FloodPlan>('/operations/flood-plans')]); events.value = eventData.items; assets.value = assetData.items; statistics.value = statsData.data; plans.value = planData } catch (e) { error.value = problemMessage(e) } finally { loading.value = false } }
async function createEvent(): Promise<void> { if (!form.title || !form.description) return ElMessage.warning('请填写事件标题与描述。'); submitting.value = true; try { await post('/emergency/events', { ...form, assetId: form.assetId || undefined }); dialog.value = false; await load(); ElMessage.success('事件已创建，可在详情中分派工单。') } catch (e) { ElMessage.error(problemMessage(e)) } finally { submitting.value = false } }
async function createPlan(): Promise<void> { if (!plan.name || !plan.content) return ElMessage.warning('请填写预案标题、区域和内容。'); try { await post('/operations/flood-plans', plan); planDialog.value = false; Object.assign(plan, { name: '', content: '', status: 'Active' }); await load(); ElMessage.success('防汛防台预案已保存。') } catch (e) { ElMessage.error(problemMessage(e)) } }
onMounted(() => { void load() })
</script>
<template><div class="page"><div class="page-heading"><div><h1>应急与外部协同</h1><p>管理事件发现、人工处置、办结与防汛预案；事件、告警、工单状态彼此独立。</p></div><el-space><el-button @click="planDialog = true">维护防汛预案</el-button><el-button type="primary" @click="dialog = true">人工创建事件</el-button></el-space></div><section class="event-stats"><article class="surface"><span>开放</span><b>{{ statistics.open ?? 0 }}</b></article><article class="surface"><span>事件总数</span><b>{{ (statistics.total ?? 0) }}</b></article><article class="surface"><span>办结率（%）</span><b>{{ statistics.closureRate ?? 0 }}</b></article><article class="surface"><span>已办结</span><b>{{ statistics.closed ?? 0 }}</b></article><article class="surface"><span>平均处置时长</span><b>{{ statistics.averageProcessingHours ?? '—' }}<small> h</small></b></article></section><el-alert v-if="error" type="error" :title="error" :closable="false" /><section class="surface table-panel" v-loading="loading"><el-table :data="events" empty-text="暂无事件"><el-table-column prop="number" label="事件编号" width="145" /><el-table-column prop="title" label="事件标题" min-width="210" /><el-table-column prop="category" label="类别" width="120" /><el-table-column prop="severity" label="级别" width="100" /><el-table-column label="状态" width="140"><template #default="scope"><StatusTag :status="scope.row.status" /></template></el-table-column><el-table-column label="操作" width="110"><template #default="scope"><el-button link type="primary" @click="$router.push(`/admin/emergency/${scope.row.id}`)">处置详情</el-button></template></el-table-column></el-table></section><section class="surface plans"><div class="data-title">防汛防台预案台账</div><el-table :data="plans" empty-text="暂无预案"><el-table-column prop="name" label="预案名称" /><el-table-column prop="status" label="状态" /><el-table-column prop="content" label="检查与处置要求" /></el-table></section><el-dialog v-model="dialog" title="人工创建事件" width="650px"><el-form label-position="top"><div class="form-row"><el-form-item label="事件标题"><el-input v-model="form.title" /></el-form-item><el-form-item label="类别"><el-select v-model="form.category"><el-option value="Environment" /><el-option value="Facility" /><el-option value="Security" /><el-option value="Flood" /><el-option value="Plant" /></el-select></el-form-item></div><div class="form-row"><el-form-item label="级别"><el-select v-model="form.severity"><el-option value="Warning" /><el-option value="Critical" /></el-select></el-form-item><el-form-item label="关联资产"><el-select v-model="form.assetId" clearable filterable><el-option v-for="asset in assets" :key="asset.id" :value="asset.id" :label="`${asset.code} · ${asset.name}`" /></el-select></el-form-item></div><el-form-item label="事件描述"><el-input v-model="form.description" type="textarea" :rows="4" /></el-form-item><div class="form-row"><el-form-item label="经度"><el-input-number v-model="form.longitude" :precision="6" /></el-form-item><el-form-item label="纬度"><el-input-number v-model="form.latitude" :precision="6" /></el-form-item></div></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="submitting" @click="createEvent">创建事件</el-button></template></el-dialog><el-dialog v-model="planDialog" title="新增防汛防台预案" width="600px"><el-form label-position="top"><el-form-item label="预案标题"><el-input v-model="plan.name" /></el-form-item><el-form-item label="预案状态"><el-input v-model="plan.status" /></el-form-item><el-form-item label="预案内容"><el-input v-model="plan.content" type="textarea" :rows="6" placeholder="填写检查项目、重点区域和应急处置要求" /></el-form-item></el-form><template #footer><el-button @click="planDialog = false">取消</el-button><el-button type="primary" @click="createPlan">保存预案</el-button></template></el-dialog></div></template>
<style scoped>.event-stats { display:grid; grid-template-columns:repeat(5,1fr); gap:14px; margin-bottom:18px; }.event-stats article { padding:15px; }.event-stats span { display:block; color:#758680; font-size:12px; }.event-stats b { display:block; margin-top:6px; color:#38705e; font-size:27px; }.event-stats small { font-size:12px; }.table-panel,.plans { padding:18px; margin-top:16px; }.plans .data-title { margin-bottom:14px; }.form-row { display:grid; grid-template-columns:1fr 1fr; gap:14px; }</style>
